import consts from './common/consts';
import { getParsedDate, getDaysCount } from './common/utils';
import  { DatepickerOptions } from './Default';

type HotKeyAction = (dateParts: { month: number, year: number, date: number }, dp: any) => void;
type KeyCombination = string[];
type HotKeyMapKey = KeyCombination | KeyCombination[];

export default class DatepickerKeyboard {
    dp: any; // Replace with Datepicker class type
    opts: DatepickerOptions;
    pressedKeys: Set<string> = new Set();
    hotKeys: Map<HotKeyMapKey, HotKeyAction> = new Map([
        [[['Control', 'ArrowRight'], ['Control', 'ArrowUp']], (dateParts) => { dateParts.month++ }],
        [[['Control', 'ArrowLeft'], ['Control', 'ArrowDown']], (dateParts) => { dateParts.month-- }],
        [[['Shift', 'ArrowRight'], ['Shift', 'ArrowUp']], (dateParts) => { dateParts.year++ }],
        [[['Shift', 'ArrowLeft'], ['Shift', 'ArrowDown']], (dateParts) => { dateParts.year-- }],
        [[['Alt', 'ArrowRight'], ['Alt', 'ArrowUp']], (dateParts) => { dateParts.year += 10 }],
        [[['Alt', 'ArrowLeft'], ['Alt', 'ArrowDown']], (dateParts) => { dateParts.year -= 10 }],
        [['Control', 'Shift', 'ArrowUp'], (dateParts, dp) => dp.up()],
    ]);

    constructor({ dp, opts }: { dp: any, opts: DatepickerOptions }) {
        this.dp = dp;
        this.opts = opts;
        this.init();
    }

    init(): void {
        this.bindKeyboardEvents();
    }

    bindKeyboardEvents(): void {
        const { $el } = this.dp;
        $el.addEventListener('keydown', this.onKeyDown);
        $el.addEventListener('keyup', this.onKeyUp);
    }

    destroy(): void {
        const { $el } = this.dp;
        $el.removeEventListener('keydown', this.onKeyDown);
        $el.removeEventListener('keyup', this.onKeyUp);
        this.pressedKeys.clear();
    }

    getInitialFocusDate(): Date {
        const { focusDate, currentView, selectedDates, parsedViewDate: { year, month } } = this.dp;
        let potentialFocused: Date = focusDate || selectedDates[selectedDates.length - 1];

        if (!potentialFocused) {
            switch (currentView) {
                case consts.days:
                    potentialFocused = new Date(year, month, new Date().getDate());
                    break;
                case consts.months:
                    potentialFocused = new Date(year, month, 1);
                    break;
                case consts.years:
                    potentialFocused = new Date(year, 0, 1);
                    break;
            }
        }

        return potentialFocused;
    }

    focusNextCell(keyName: string): void {
        const initialFocusDate = this.getInitialFocusDate();
        const { currentView } = this.dp;
        const parsedFocusDate = getParsedDate(initialFocusDate);
        
        let y = parsedFocusDate.year,
            m = parsedFocusDate.month,
            d = parsedFocusDate.date;

        switch (keyName) {
            case 'ArrowLeft':
                currentView === consts.days ? (d -= 1) : null;
                currentView === consts.months ? (m -= 1) : null;
                currentView === consts.years ? (y -= 1) : null;
                break;
            case 'ArrowUp':
                currentView === consts.days ? (d -= 7) : null;
                currentView === consts.months ? (m -= 3) : null;
                currentView === consts.years ? (y -= 4) : null;
                break;
            case 'ArrowRight':
                currentView === consts.days ? (d += 1) : null;
                currentView === consts.months ? (m += 1) : null;
                currentView === consts.years ? (y += 1) : null;
                break;
            case 'ArrowDown':
                currentView === consts.days ? (d += 7) : null;
                currentView === consts.months ? (m += 3) : null;
                currentView === consts.years ? (y += 4) : null;
                break;
        }

        const newFocusedDate = this.dp.getClampedDate(new Date(y, m, d));
        this.dp.setFocusDate(newFocusedDate, { viewDateTransition: true });
    }

    registerKey(keyName: string): void {
        this.pressedKeys.add(keyName);
    }

    removeKey(keyName: string): void {
        this.pressedKeys.delete(keyName);
    }

    handleHotKey = (combination: HotKeyMapKey): void => {
        const fn = this.hotKeys.get(combination);
        const dateParts = getParsedDate(this.getInitialFocusDate());

        if (!fn) return;

        fn(dateParts, this.dp);

        let { year, month, date } = dateParts;
        const totalDaysInNextMonth = getDaysCount(new Date(year, month));

        if (totalDaysInNextMonth < date) {
            date = totalDaysInNextMonth;
        }

        const newFocusedDate = this.dp.getClampedDate(new Date(year, month, date));
        this.dp.setFocusDate(newFocusedDate, { viewDateTransition: true });
    }

    isHotKeyPressed = (): HotKeyMapKey | false => {
        let hotKeyCombination: HotKeyMapKey | false = false;
        const pressedKeysLength = this.pressedKeys.size;
        const isAllKeysArePressed = (key: string) => this.pressedKeys.has(key);

        for (const [combinations] of this.hotKeys) {
            if (hotKeyCombination) break;

            if (Array.isArray(combinations[0])) {
                (combinations as KeyCombination[]).forEach((combination) => {
                    if (hotKeyCombination || pressedKeysLength !== combination.length) return;
                    if (combination.every(isAllKeysArePressed)) {
                        hotKeyCombination = combinations;
                    }
                });
            } else {
                const combination = combinations as KeyCombination;
                if (pressedKeysLength !== combination.length) continue;
                if (combination.every(isAllKeysArePressed)) {
                    hotKeyCombination = combinations;
                }
            }
        }

        return hotKeyCombination;
    }

    isArrow = (keyCode: number): boolean => {
        return keyCode >= 37 && keyCode <= 40;
    }

    onKeyDown = (e: KeyboardEvent): void => {
        if (!this.dp.visible && !this.dp.treatAsInline) return;

        const { key, which } = e;
        const { dp, opts } = this;

        this.registerKey(key);

        const pressedHotKey = this.isHotKeyPressed();

        if (pressedHotKey) {
            e.preventDefault();
            this.handleHotKey(pressedHotKey);
            return;
        }

        if (this.isArrow(which)) {
            e.preventDefault();
            this.focusNextCell(key);
            return;
        }

        if (key === 'Enter') {
            if (dp.currentView !== opts.minView) {
                dp.down();
                return;
            }
            if (dp.focusDate) {
                const alreadySelectedDate = dp._checkIfDateIsSelected(dp.focusDate);
                if (!alreadySelectedDate) {
                    dp.selectDate(dp.focusDate);
                } else {
                    dp._handleAlreadySelectedDates(alreadySelectedDate, dp.focusDate);
                }
                return;
            }
        }

        if (key === 'Escape') {
            this.dp.hide();
        }
    }

    onKeyUp = (e: KeyboardEvent): void => {
        this.removeKey(e.key);
    }
}